    </nav>
</header>

<div class="hero">
    <h1>畅行旅行</h1>
</div>

<div class="search-box">
    <label for="destination">目的地</label>
    <input type="text" id="destination" placeholder="输入城市或景点">
    <label for="start-date">出发日期</label>
    <input type="date" id="start-date">
    <label for="end-date">返回日期</label>
    <input type="date" id="end-date">
    <button type="button" onclick="location.href='results.html'">搜索酒店</button>
